package app.tubehaus.ui

import app.tubehaus.patch.Patchable
import kotlin.concurrent.Volatile

// Interface text. English is the key; other languages map it. A missing translation shows English.

object L {
    @Volatile var lang = "en"
}

/** YouTube's "Sign in to confirm you're not a bot": it asks that of VPN and data-center addresses */
const val BOT_CHECK = "YouTube wants this network to sign in, which it often does for VPNs and data centers. Try again without a VPN, or on another network."

val LANGS = listOf(
    "en" to "English", "ko" to "한국어", "es" to "Español", "ja" to "日本語", "de" to "Deutsch",
    "zh" to "简体中文", "pt" to "Português", "fr" to "Français", "ru" to "Русский", "hi" to "हिन्दी", "id" to "Bahasa Indonesia", "tr" to "Türkçe", "bn" to "বাংলা",
)

fun tr(s: String): String {
    textOverride(s, L.lang).let { if (it.isNotEmpty()) return it }
    return when (L.lang) {
        "ko" -> KO[s] ?: s
        "es" -> ES[s] ?: s
        "ja" -> JA[s] ?: s
        "de" -> DE[s] ?: s
        "zh" -> ZH[s] ?: s
        "pt" -> PT[s] ?: s
        "fr" -> FR[s] ?: s
        "ru" -> RU[s] ?: s
        "hi" -> HI[s] ?: s
        "id" -> ID[s] ?: s
        "tr" -> TR[s] ?: s
        "bn" -> BN[s] ?: s
        else -> s
    }
}

/**
 * A text of the app's own, in place of [key]'s translation; "" keeps the translation. Always ""
 * here: on the iPad, patch.js can answer instead (TubePatch) and change any text without a new build.
 */
@Patchable
fun textOverride(key: String, lang: String): String = ""

