    "TubeHaus is independent, free, open-source software, not affiliated with YouTube or Google. It doesn't host any videos and comes with no warranty. Downloaded videos are for your own viewing: sharing or re-uploading them is your own responsibility. Use it in line with your local laws and the terms of the services it connects to." to "TubeHaus는 개인이 만든 무료 오픈소스 앱이고, 유튜브나 구글과 관계가 없어요. 영상을 저장하거나 배포하지 않고, 어떤 보증도 하지 않아요. 내려받은 영상은 본인이 보는 용도로만 쓰세요. 공유하거나 다시 올리는 건 그렇게 한 사람의 책임이에요. 사는 곳의 법과 연결하는 서비스의 약관에 맞게 써 주세요.",
