    "TubeHaus is independent, free, open-source software, not affiliated with YouTube or Google. It doesn't host any videos and comes with no warranty. Downloaded videos are for your own viewing: sharing or re-uploading them is your own responsibility. Use it in line with your local laws and the terms of the services it connects to." to "TubeHaus एक स्वतंत्र, मुफ़्त, ओपन-सोर्स सॉफ़्टवेयर है, जिसका YouTube या Google से कोई संबंध नहीं है. यह कोई वीडियो होस्ट नहीं करता और इसके साथ कोई वारंटी नहीं है. डाउनलोड किए गए वीडियो आपके अपने देखने के लिए हैं: उन्हें शेयर करना या दोबारा अपलोड करना आपकी अपनी ज़िम्मेदारी है. इसे अपने स्थानीय कानूनों और जिन सेवाओं से यह जुड़ता है उनकी शर्तों के अनुसार इस्तेमाल करें.",
    "For your own viewing only. Sharing or re-uploading it is your own responsibility." to "सिर्फ़ आपके अपने देखने के लिए. इसे शेयर करना या दोबारा अपलोड करना आपकी अपनी ज़िम्मेदारी है.",
