    "TubeHaus is independent, free, open-source software, not affiliated with YouTube or Google. It doesn't host any videos and comes with no warranty. Downloaded videos are for your own viewing: sharing or re-uploading them is your own responsibility. Use it in line with your local laws and the terms of the services it connects to." to "TubeHaus একটি স্বাধীন, বিনামূল্যের, ওপেন-সোর্স সফটওয়্যার, YouTube বা Google-এর সাথে কোনো সম্পর্ক নেই। এটি কোনো ভিডিও হোস্ট করে না এবং কোনো ওয়ারেন্টি দেয় না। ডাউনলোড করা ভিডিও আপনার নিজের দেখার জন্য: সেগুলো শেয়ার বা আবার আপলোড করা আপনার নিজের দায়িত্ব। স্থানীয় আইন আর এটি যেসব সেবার সাথে যুক্ত হয় তাদের শর্ত মেনে ব্যবহার করুন।",
